Dataspatium.assets.register("presets/api/luftkvalitet.api.json","text","{\n  \"format\": \"dataspatium-api/1\",\n  \"id\": \"luftkvalitet\",\n  \"name\": \"Luftkvalitet (Naturvårdsverkets datavärdskap)\",\n  \"publisher\": \"Naturvårdsverket, datavärd SMHI\",\n  \"description\": \"Mätningar av luftföroreningar (NO2, PM10, PM2.5, ozon med mera) från Sveriges mätstationer. Lista stationer och tidsserier, hämta sedan värden för en tidsserie och ett tidsintervall.\",\n  \"docs\": \"https://datavardluft.smhi.se/\",\n  \"license\": { \"name\": \"Öppna data, se datavärdskapets villkor\", \"url\": \"https://datavardluft.smhi.se/\" },\n  \"level\": 1,\n  \"country\": \"SE\",\n  \"baseUrl\": \"https://datavardluft.smhi.se/52North/api\",\n  \"auth\": { \"type\": \"none\" },\n  \"rateLimit\": { \"requests\": 10, \"perSeconds\": 2 },\n  \"endpoints\": [\n    {\n      \"id\": \"stations\",\n      \"name\": \"Mätstationer\",\n      \"method\": \"GET\",\n      \"path\": \"/stations\",\n      \"params\": [\n        { \"name\": \"expanded\", \"in\": \"query\", \"type\": \"string\", \"default\": \"true\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"geojson\", \"options\": { \"geometry\": false }, \"rename\": { \"label\": \"station\", \"classification\": \"klassning\", \"id\": \"station_id\" } },\n      \"dataset\": { \"name\": \"Luftkvalitet mätstationer\" }\n    },\n    {\n      \"id\": \"timeseries\",\n      \"name\": \"Tidsserier\",\n      \"description\": \"Alla tidsserier med station, ämne, enhet och period. Kolumnen id används för att hämta värden.\",\n      \"method\": \"GET\",\n      \"path\": \"/timeseries\",\n      \"params\": [\n        { \"name\": \"station\", \"in\": \"query\", \"label\": \"Station (id, valfritt)\", \"type\": \"string\" },\n        { \"name\": \"phenomenon\", \"in\": \"query\", \"label\": \"Ämne (id, valfritt)\", \"type\": \"string\" },\n        { \"name\": \"expanded\", \"in\": \"query\", \"type\": \"string\", \"default\": \"true\", \"hidden\": true }\n      ],\n      \"response\": { \"format\": \"json\", \"convert\": { \"firstValue.timestamp\": \"epoch-ms\", \"lastValue.timestamp\": \"epoch-ms\" }, \"rename\": { \"label\": \"tidsserie\", \"uom\": \"enhet\", \"station.properties.label\": \"station\", \"station.id\": \"station_id\", \"parameters.phenomenon.label\": \"amne\", \"parameters.phenomenon.id\": \"amne_id\", \"firstValue.timestamp\": \"forsta_tid\", \"lastValue.timestamp\": \"senaste_tid\", \"firstValue.value\": \"forsta_varde\", \"lastValue.value\": \"senaste_varde\" }, \"drop\": [\"extras\", \"aggregationTypes\", \"station.type\", \"station.geometry.type\", \"station.properties.classification\", \"parameters.procedure.id\", \"parameters.procedure.label\", \"parameters.category.id\", \"parameters.category.label\", \"parameters.offering.id\", \"parameters.offering.label\", \"parameters.feature.id\", \"parameters.feature.label\", \"parameters.service.id\", \"parameters.service.label\", \"renderingHints\", \"statusIntervals\"] },\n      \"dataset\": { \"name\": \"Luftkvalitet tidsserier\" }\n    },\n    {\n      \"id\": \"data\",\n      \"name\": \"Värden för en tidsserie\",\n      \"method\": \"GET\",\n      \"path\": \"/timeseries/{id}/getData\",\n      \"params\": [\n        { \"name\": \"id\", \"in\": \"path\", \"label\": \"Tidsserie (id från listan Tidsserier)\", \"type\": \"string\", \"required\": true, \"example\": \"78\" },\n        { \"name\": \"timespan\", \"in\": \"query\", \"label\": \"Tidsintervall (ISO 8601)\", \"type\": \"string\", \"required\": true, \"example\": \"2024-01-01T00:00:00Z/2024-01-31T23:00:00Z\", \"help\": \"Start/slut, eller en längd och en sluttid som PT24H/2026-11-02T00:00:00Z.\" }\n      ],\n      \"response\": { \"format\": \"json\", \"path\": \"values\", \"convert\": { \"timestamp\": \"epoch-ms\" }, \"rename\": { \"timestamp\": \"tid\", \"value\": \"varde\" } },\n      \"dataset\": { \"name\": \"Luftkvalitet tidsserie {id}\", \"keys\": [\"tid\"] }\n    }\n  ],\n  \"i18n\": {\n    \"en\": {\"name\": \"Air quality (Swedish EPA data host)\", \"publisher\": \"Swedish Environmental Protection Agency, data host SMHI\", \"description\": \"Measurements of air pollutants (NO2, PM10, PM2.5, ozone and more) from Sweden's measuring stations. List stations and time series, then fetch values for a time series and a time interval.\", \"endpoints\": {\"stations\": {\"name\": \"Measuring stations\"}, \"timeseries\": {\"name\": \"Time series\", \"description\": \"All time series with station, substance, unit and period. The id column is used to fetch values.\", \"params\": {\"station\": {\"label\": \"Station (id, optional)\"}, \"phenomenon\": {\"label\": \"Substance (id, optional)\"}}}, \"data\": {\"name\": \"Values for a time series\", \"params\": {\"id\": {\"label\": \"Time series (id from the Time series list)\"}, \"timespan\": {\"label\": \"Time interval (ISO 8601)\", \"help\": \"Start/end, or a duration and an end time such as PT24H/2026-11-02T00:00:00Z.\"}}}}, \"dataset\": {\"stations\": \"Air quality measuring stations\", \"timeseries\": \"Air quality time series\", \"data\": \"Air quality time series {id}\"}},\n    \"da\": {\"name\": \"Luftkvalitet (svensk miljømyndigheds dataværtskab)\", \"publisher\": \"Naturvårdsverket, dataværtskab SMHI\", \"description\": \"Målinger af luftforurening (NO2, PM10, PM2,5, ozon med mere) fra Sveriges målestationer. Vis stationer og tidsserier, og hent derefter værdier for en tidsserie og et tidsinterval.\", \"endpoints\": {\"stations\": {\"name\": \"Målestationer\"}, \"timeseries\": {\"name\": \"Tidsserier\", \"description\": \"Alle tidsserier med station, stof, enhed og periode. Kolonnen id bruges til at hente værdier.\", \"params\": {\"station\": {\"label\": \"Station (id, valgfrit)\"}, \"phenomenon\": {\"label\": \"Stof (id, valgfrit)\"}}}, \"data\": {\"name\": \"Værdier for en tidsserie\", \"params\": {\"id\": {\"label\": \"Tidsserie (id fra listen Tidsserier)\"}, \"timespan\": {\"label\": \"Tidsinterval (ISO 8601)\", \"help\": \"Start/slut eller en varighed og et sluttidspunkt som PT24H/2026-11-02T00:00:00Z.\"}}}}, \"dataset\": {\"stations\": \"Luftkvalitet målestationer\", \"timeseries\": \"Luftkvalitet tidsserier\", \"data\": \"Luftkvalitet tidsserie {id}\"}},\n    \"nb\": {\"name\": \"Luftkvalitet (svensk miljømyndighets dataverttjeneste)\", \"publisher\": \"Naturvårdsverket, dataverttjeneste SMHI\", \"description\": \"Målinger av luftforurensninger (NO2, PM10, PM2,5, ozon med mer) fra Sveriges målestasjoner. List stasjoner og tidsserier, og hent deretter verdier for en tidsserie og et tidsintervall.\", \"endpoints\": {\"stations\": {\"name\": \"Målestasjoner\"}, \"timeseries\": {\"name\": \"Tidsserier\", \"description\": \"Alle tidsserier med stasjon, stoff, enhet og periode. Kolonnen id brukes for å hente verdier.\", \"params\": {\"station\": {\"label\": \"Stasjon (id, valgfritt)\"}, \"phenomenon\": {\"label\": \"Stoff (id, valgfritt)\"}}}, \"data\": {\"name\": \"Verdier for en tidsserie\", \"params\": {\"id\": {\"label\": \"Tidsserie (id fra listen Tidsserier)\"}, \"timespan\": {\"label\": \"Tidsintervall (ISO 8601)\", \"help\": \"Start/slutt, eller en varighet og et sluttidspunkt som PT24H/2026-11-02T00:00:00Z.\"}}}}, \"dataset\": {\"stations\": \"Luftkvalitet målestasjoner\", \"timeseries\": \"Luftkvalitet tidsserier\", \"data\": \"Luftkvalitet tidsserie {id}\"}},\n    \"fi\": {\"name\": \"Ilmanlaatu (Ruotsin ympäristöviraston datapalvelu)\", \"publisher\": \"Naturvårdsverket, datapalvelu SMHI\", \"description\": \"Ilman epäpuhtauksien (NO2, PM10, PM2,5, otsoni ja muut) mittaukset Ruotsin mittausasemilta. Luettele asemat ja aikasarjat ja nouda sitten arvot aikasarjalle ja aikavälille.\", \"endpoints\": {\"stations\": {\"name\": \"Mittausasemat\"}, \"timeseries\": {\"name\": \"Aikasarjat\", \"description\": \"Kaikki aikasarjat asemineen, aineineen, yksiköineen ja jaksoineen. Saraketta id käytetään arvojen noutamiseen.\", \"params\": {\"station\": {\"label\": \"Asema (id, valinnainen)\"}, \"phenomenon\": {\"label\": \"Aine (id, valinnainen)\"}}}, \"data\": {\"name\": \"Aikasarjan arvot\", \"params\": {\"id\": {\"label\": \"Aikasarja (id luettelosta Aikasarjat)\"}, \"timespan\": {\"label\": \"Aikaväli (ISO 8601)\", \"help\": \"Alku/loppu tai kesto ja loppuaika, kuten PT24H/2026-11-02T00:00:00Z.\"}}}}, \"dataset\": {\"stations\": \"Ilmanlaatu mittausasemat\", \"timeseries\": \"Ilmanlaatu aikasarjat\", \"data\": \"Ilmanlaatu aikasarja {id}\"}},\n    \"is\": {\"name\": \"Loftgæði (gagnaþjónusta sænsku umhverfisstofnunarinnar)\", \"publisher\": \"Naturvårdsverket, gagnaþjónusta SMHI\", \"description\": \"Mælingar á loftmengun (NO2, PM10, PM2,5, óson og fleira) frá mælistöðvum í Svíþjóð. Listaðu stöðvar og tímaraðir og sæktu síðan gildi fyrir tímaröð og tímabil.\", \"endpoints\": {\"stations\": {\"name\": \"Mælistöðvar\"}, \"timeseries\": {\"name\": \"Tímaraðir\", \"description\": \"Allar tímaraðir með stöð, efni, einingu og tímabili. Dálkurinn id er notaður til að sækja gildi.\", \"params\": {\"station\": {\"label\": \"Stöð (auðkenni, valfrjálst)\"}, \"phenomenon\": {\"label\": \"Efni (auðkenni, valfrjálst)\"}}}, \"data\": {\"name\": \"Gildi fyrir tímaröð\", \"params\": {\"id\": {\"label\": \"Tímaröð (auðkenni úr listanum Tímaraðir)\"}, \"timespan\": {\"label\": \"Tímabil (ISO 8601)\", \"help\": \"Upphaf/lok, eða tímalengd og lokatími eins og PT24H/2026-11-02T00:00:00Z.\"}}}}, \"dataset\": {\"stations\": \"Loftgæði mælistöðvar\", \"timeseries\": \"Loftgæði tímaraðir\", \"data\": \"Loftgæði tímaröð {id}\"}}\n  }\n}\n");
